export function planar(p,t,lane,out=[0,0,0]){
 const phase=p.phase;
 // Shared full contour, scaled inward rather than displaced along radial normals.
 const q=t+.10*Math.sin(t+phase)+.045*p.air*Math.sin(2*t-phase);
 const turn=q+.10*Math.sin(Math.PI*lane)*Math.sin(2*q-phase);
 const radius=1.92+.32*Math.sin(3*q+phase)+.13*Math.sin(2*q-phase)+.06*(1-p.pitch)*Math.sin(q+phase);
 const depth=lane+.045*Math.sin(lane*TAU+phase)*Math.sin(Math.PI*lane);
 const scale=1-(.29+.05*p.air)*depth;
 const drift=.028*Math.sin(Math.PI*lane)*Math.sin(3*q+lane*8+phase);
 const r=radius*scale+drift;
 out[0]=Math.cos(turn)*r;out[2]=Math.sin(turn)*r;
 out[1]=.028+.022*Math.sin(3*t+phase)+.004*(lane-.5)*Math.sin(3*q+phase);
 return out;
}

export function planar(p,t,lane,out=[0,0,0]){
 const phase=p.phase;
 // Shared full contour, scaled inward rather than displaced along radial normals.
 const q=t+.10*Math.sin(t+phase)+.045*p.air*Math.sin(2*t-phase);
 const turn=q+(.48+.18*p.brightness)*Math.sin(Math.PI*lane)+.06*Math.sin(Math.PI*lane)*Math.sin(2*q-phase);
 const radius=1.92+.32*Math.sin(3*q+phase)+.13*Math.sin(2*q-phase)+.06*(1-p.pitch)*Math.sin(q+phase);
 const depth=lane+.045*Math.sin(lane*TAU+phase)*Math.sin(Math.PI*lane);
 const scale=1-(.29+.05*p.air)*depth;
 const drift=.028*Math.sin(Math.PI*lane)*Math.sin(3*q+lane*8+phase);
 const r=radius*scale+drift;
 out[0]=Math.cos(turn)*r;out[2]=Math.sin(turn)*r;
 out[1]=.028+.022*Math.sin(3*t+phase)+.004*(lane-.5)*Math.sin(3*q+phase);
 return out;
}
